#!/usr/bin/env bash
# Generated by `dotai init`. Both Claude Code (.claude/settings.json) and
# Copilot (.github/hooks/lint.json) call this one script, so the check lives
# here and nowhere else.
set -euo pipefail

if ! yarn lint 2>&1; then
  echo "Lint failed. Fix the reported issues before continuing." >&2
  exit 2
fi

exit 0
